/* delBuyerMpRqTempSaveList */
UPDATE	KEPRQDT
SET		RECV_FLAG = 'GD'
		, CANCEL_USER_ID	= #{st_user_id}
	    , CANCEL_DATE		= SYSDATE
	    , CANCEL_REMARK		= '견적요청 품의로 인한 임시저장 취소건(복원 금지)'
	    , STATUS  			= 'D'
WHERE	1=1
AND		BUYER = #{st_buyer}
AND		QUOTATION_NO = #{st_quotation_no}
AND		QUOTATION_SEQ = #{st_quotation_seq}
AND		REVISION = #{st_revision}
AND		STATUS IN ('C', 'R')

/* setRqdtRecvFlagToNg */
UPDATE	KEPRQDT
SET		RECV_FLAG = 'NG'
WHERE	1=1
AND		BUYER = #{COMPANY}
AND		GW_GA_NO = #{BIZ_DOCU_NO}
AND		STATUS IN ('C', 'R')
